def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    D = [int(next(it)) for _ in range(N)]
    L1 = int(next(it)); C1 = int(next(it)); K1 = int(next(it))
    L2 = int(next(it)); C2 = int(next(it)); K2 = int(next(it))

    INF = 10**18
    dp = [INF] * (K1 + 1)
    dp[0] = 0

    for d in D:
        # generate candidate (x, y) pairs for this section
        max_x = min(K1, (d + L1 - 1) // L1)  # ceil(d / L1)
        candidates = []
        for x in range(max_x + 1):
            # minimal y such that x*L1 + y*L2 >= d
            need = d - x * L1
            if need <= 0:
                y = 0
            else:
                y = (need + L2 - 1) // L2  # ceil(need / L2)
            if y <= K2:
                candidates.append((x, y))
        # DP update
        new_dp = [INF] * (K1 + 1)
        for a in range(K1 + 1):
            cur = dp[a]
            if cur == INF:
                continue
            for x, y in candidates:
                na = a + x
                if na > K1:
                    continue
                val = cur + y
                if val < new_dp[na]:
                    new_dp[na] = val
        dp = new_dp

    ans = INF
    for a in range(K1 + 1):
        b = dp[a]
        if b <= K2:
            cost = a * C1 + b * C2
            if cost < ans:
                ans = cost

    if ans == INF:
