def can_make_square(grid):
    # Check all four possible 2x2 squares in a 3x3 grid
    for top in range(2):          # row of top-left corner: 0 or 1
        for left in range(2):     # column of top-left corner: 0 or 1
            # Count black and white cells in this 2x2 square
            black = 0
            white = 0
            for i in range(top, top + 2):
                for j in range(left, left + 2):
                    if grid[i][j] == 'B':
                        black += 1
                    else:
                        white += 1
            # If one color appears at least 3 times, we can make the square uniform
            # by changing at most one cell (0 changes if already 4, 1 change if 3)
            if black >= 3 or white >= 3:
                return True
    return False
