def isValid(word: str) -> bool:
    # Check length constraint
    if len(word) < 3:
        return False

    # Define allowed characters: digits and English letters only
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")

    # Flags for vowel and consonant presence
    has_vowel = False
    has_consonant = False

    for ch in word:
        # Check if character is allowed
        if ch not in allowed_chars:
            return False

        # Check for vowel or consonant (only for letters)
        if ch.isalpha():
            if ch.lower() in "aeiou":
                has_vowel = True
            else:
                has_consonant = True

    # Final validation
    return has_vowel and has_consonant
