def numberOfSpecialChars(word: str) -> int:
    # Create a set of all lowercase letters present in the word
    lower_set = {c for c in word if c.islower()}
    # Create a set of lowercase versions of all uppercase letters present
    upper_set = {c.lower() for c in word if c.isupper()}
    # Special letters are those that appear in both sets
    special = lower_set & upper_set
    return len(special)
