import sys
import itertools

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))
    edges = []
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        edges.append((u, v, w))

    # Union-Find helper
    class DSU:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, x, y):
            xr = self.find(x)
            yr = self.find(y)
            if xr == yr:
                return False
            if self.rank[xr] < self.rank[yr]:
                self.parent[xr] = yr
            elif self.rank[xr] > self.rank[yr]:
                self.parent[yr] = xr
            else:
                self.parent[yr] = xr
                self.rank[xr] += 1
            return True

    min_cost = None
    # Enumerate all subsets of edges of size N-1
    for combo in itertools.combinations(range(M), N-1):
        dsu = DSU(N)
        total = 0
        ok = True
        for idx in combo:
            u, v, w = edges[idx]
            if not dsu.union(u, v):
                ok = False
                break
            total += w
        if not ok:
            continue
        # Check connectivity: all vertices should have the same root
        root = dsu.find(0)
        connected = True
        for v in range(1, N):
            if dsu.find(v) != root:
                connected = False
                break
        if connected:
            cost = total % K
            if min_cost is None or cost < min_cost:
                min_cost = cost
                # Early exit if we found 0 (cannot be better)
                if min_cost == 0:
                    break

    print(min_cost)

if __name__ == "__main__":
    solve()
