import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    INF = 10**18
    # 0-indexed vertices
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        dist[u][v] = min(dist[u][v], w)  # no parallel edges, but safe
    # Floyd-Warshall
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF:
                continue
            for j in range(N):
                if dist[k][j] == INF:
                    continue
                nd = dist[i][k] + dist[k][j]
                if nd < dist[i][j]:
                    dist[i][j] = nd
    # DP over subsets (TSP)
    full_mask = (1 << N) - 1
    dp = [[INF] * N for _ in range(1 << N)]
    for i in range(N):
        dp[1 << i][i] = 0
    for mask in range(1 << N):
        for u in range(N):
            if not (mask >> u) & 1:
                continue
            if dp[mask][u] == INF:
                continue
            for v in range(N):
                if (mask >> v) & 1:
                    continue
                if dist[u][v] == INF:
                    continue
                new_mask = mask | (1 << v)
                nd = dp[mask][u] + dist[u][v]
                if nd < dp[new_mask][v]:
                    dp[new_mask][v] = nd
    ans = min(dp[full_mask])
    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
