from typing import List

def numberOfRightTriangles(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    row_count = [0] * m
    col_count = [0] * n

    # Count ones in each row and column
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                row_count[i] += 1
                col_count[j] += 1

    ans = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                # Number of triangles with (i,j) as the right-angle vertex
                ans += (row_count[i] - 1) * (col_count[j] - 1)

    return ans
