from functools import lru_cache

def beautifulNumbers(low: int, high: int, k: int) -> int:
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        s = str(n)

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, leading_zero: bool, diff: int, mod: int) -> int:
            if pos == len(s):
                return 1 if (not leading_zero) and diff == 0 and mod == 0 else 0

            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_leading_zero = leading_zero and (d == 0)
                if new_leading_zero:
                    new_diff = diff
                    new_mod = mod
                else:
                    # d is part of the number
                    if d % 2 == 0:
                        new_diff = diff + 1
                    else:
                        new_diff = diff - 1
                    new_mod = (mod * 10 + d) % k
                total += dp(pos + 1, new_tight, new_leading_zero, new_diff, new_mod)
            return total

        return dp(0, True, True, 0, 0)

    return count_up_to(high) - count_up_to(low - 1)
