                right[i][j] = j
            else:
                right[i][j] = right[i][j+1] if j < M-1 else M-1

    # up[i][j] = row of nearest rock above
    up = [[0] * M for _ in range(N)]
    for j in range(M):
        for i in range(N):
            if grid[i][j] == '#':
                up[i][j] = i
            else:
                up[i][j] = up[i-1][j] if i > 0 else 0

    # down[i][j] = row of nearest rock below
    down = [[0] * M for _ in range(N)]
    for j in range(M):
        for i in range(N-1, -1, -1):
            if grid[i][j] == '#':
                down[i][j] = i
            else:
                down[i][j] = down[i+1][j] if i < N-1 else N-1

    visited = [[False] * M for _ in range(N)]
    # start at (2,2) in 1-indexed -> (1,1) in 0-indexed
    si, sj = 1, 1
    visited[si][sj] = True
    q = deque()
    q.append((si, sj))

    while q:
        i, j = q.popleft()

        # left
        stop_col = left[i][j] + 1
        if stop_col < j:  # actually moves
            prev = visited[i][stop_col]
            for c in range(stop_col, j+1):
                visited[i][c] = True
            if not prev:
                q.append((i, stop_col))

        # right
        stop_col = right[i][j] - 1
        if stop_col > j:
            prev = visited[i][stop_col]
            for c in range(j, stop_col+1):
                visited[i][c] = True
            if not prev:
                q.append((i, stop_col))

        # up
        stop_row = up[i][j] + 1
        if stop_row < i:
            prev = visited[stop_row][j]
            for r in range(stop_row, i+1):
                visited[r][j] = True
            if not prev:
                q.append((stop_row, j))

        # down
        stop_row = down[i][j] - 1
        if stop_row > i:
            prev = visited[stop_row][j]
            for r in range(i, stop_row+1):
                visited[r][j] = True
            if not prev:
                q.append((stop_row, j))

    # count visited ice squares
    ans = 0
    for i in range(N):
        for j in range(M):
            if visited[i][j]:
                ans += 1
    print(ans)

if __name__ == "__main__":
