def isSubstringPresent(s: str) -> bool:
    n = len(s)
    if n < 2:
        return False
    # Store all length-2 substrings of s in a set
    substrings = {s[i:i+2] for i in range(n - 1)}
    # Check if any length-2 substring of the reversed string is in the set
    rev_s = s[::-1]
    for i in range(n - 1):
        if rev_s[i:i+2] in substrings:
            return True
    return False
