def maximumLength(s: str) -> int:
    n = len(s)
    # Check lengths from longest to shortest
    for length in range(n, 0, -1):
        seen = set()
        for i in range(n - length + 1):
            sub = s[i:i+length]
            if sub in seen:
                continue
            # A special substring consists of a single repeated character
            if len(set(sub)) == 1:
                seen.add(sub)
                # Count occurrences of this special substring
                count = sum(1 for j in range(n - length + 1) if s[j:j+length] == sub)
                if count >= 3:
                    return length
    return -1
