import sys

def solve() -> None:
    data = list(map(int, sys.stdin.read().split()))
    # 3x3 grid, row-major order
    A = data[:9]

    # Precompute all winning lines (indices)
    lines = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],  # rows
        [0, 3, 6], [1, 4, 7], [2, 5, 8],  # columns
        [0, 4, 8], [2, 4, 6]              # diagonals
    ]

    def check_win(board, player):
        """Return True if `player` has three in a row."""
        for line in lines:
            if all(board[i] == player for i in line):
                return True
        return False

    def is_full(board):
        return all(cell != 0 for cell in board)

    def compute_scores(board):
        t_score = sum(A[i] for i in range(9) if board[i] == 1)
        a_score = sum(A[i] for i in range(9) if board[i] == -1)
        return t_score, a_score

    memo = {}

    def minimax(board, turn):
        """Return 1 if Takahashi wins from this state, -1 if Aoki wins."""
        key = (board, turn)
        if key in memo:
            return memo[key]

        # Terminal: board full (no line can exist because game would have ended)
        if is_full(board):
            t_score, a_score = compute_scores(board)
            result = 1 if t_score > a_score else -1
            memo[key] = result
            return result

        best = None
        for i in range(9):
            if board[i] == 0:
                new_board = list(board)
                new_board[i] = turn
                new_board = tuple(new_board)

                # Check if this move immediately wins for the current player
                if check_win(new_board, turn):
                    val = 1 if turn == 1 else -1
                else:
                    val = minimax(new_board, -turn)

                if turn == 1:  # Takahashi maximizes
                    if best is None or val > best:
                        best = val
                else:          # Aoki minimizes
                    if best is None or val < best:
                        best = val

        memo[key] = best
        return best

    initial_board = (0,) * 9
    result = minimax(initial_board, 1)  # Takahashi starts
    print("Takahashi" if result == 1 else "Aoki")

if __name__ == "__main__":
    solve()
