def minChanges(s: str, k: int) -> int:
    n = len(s)
    INF = 10**9

    # precompute all divisors for each possible length (2..n)
    divisors = [[] for _ in range(n + 1)]
    for L in range(2, n + 1):
        for d in range(1, L):
            if L % d == 0:
                divisors[L].append(d)

    # cost[i][j] = minimum changes to make substring s[i:j] a semi-palindrome
    cost = [[INF] * (n + 1) for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):          # substring length at least 2
            L = j - i
            best = INF
            for d in divisors[L]:
                changes = 0
                # for each residue class modulo d
                for r in range(d):
                    seq_len = L // d
                    # compare symmetric positions in the sequence
                    for t in range(seq_len // 2):
                        left = s[i + r + t * d]
                        right = s[i + r + (seq_len - 1 - t) * d]
                        if left != right:
                            changes += 1
                best = min(best, changes)
            cost[i][j] = best

    # dp[t][i] = min changes for first i characters partitioned into t substrings
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for t in range(1, k + 1):
        # each substring needs at least length 2, so prefix length >= 2*t
        for i in range(2 * t, n + 1):
            # previous partition must end at j, with j >= 2*(t-1) and j <= i-2
            for j in range(2 * (t - 1), i - 1):
                if dp[t - 1][j] != INF and cost[j][i] != INF:
                    dp[t][i] = min(dp[t][i], dp[t - 1][j] + cost[j][i])

    return dp[k][n]
```

