from typing import List

class TrieNode:
    __slots__ = ('children', 'best_index', 'best_length')
    def __init__(self):
        self.children = {}
        self.best_index = -1
        self.best_length = float('inf')

def longestCommonSuffix(wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
    root = TrieNode()

    # Build trie from reversed container words
    for idx, word in enumerate(wordsContainer):
        length = len(word)
        # Update root (empty suffix) with current word
        if length < root.best_length or (length == root.best_length and idx < root.best_index):
            root.best_length = length
            root.best_index = idx

        node = root
        rev = word[::-1]
        for ch in rev:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            # Update this node with current word
            if length < node.best_length or (length == node.best_length and idx < node.best_index):
                node.best_length = length
                node.best_index = idx

    # Answer queries
    ans = []
    for query in wordsQuery:
        node = root
        rev = query[::-1]
        for ch in rev:
            if ch in node.children:
                node = node.children[ch]
            else:
                break
        ans.append(node.best_index)

    return ans
