import sys

def is_one_edit(t: str, s: str) -> bool:
    """Return True if s can be transformed into t by at most one edit
    (insert, delete, replace)."""
    lt, ls = len(t), len(s)
    if lt == ls:
        # check for at most one character difference
        diff = 0
        for i in range(lt):
            if t[i] != s[i]:
                diff += 1
                if diff > 1:
                    return False
        return True
    elif lt == ls + 1:
        # t has one extra character (insertion into s)
        i = j = 0
        # find first mismatch
        while i < lt and j < ls and t[i] == s[j]:
            i += 1
            j += 1
        if j == ls:
            # extra character at the end of t
            return True
        # skip one character in t
        i += 1
        # compare the rest
        while i < lt and j < ls:
            if t[i] != s[j]:
                return False
            i += 1
            j += 1
        return True
    elif lt == ls - 1:
        # s has one extra character (deletion from s)
        i = j = 0
        while i < lt and j < ls and t[i] == s[j]:
            i += 1
            j += 1
        if i == lt:
            # extra character at the end of s
            return True
        # skip one character in s
        j += 1
        while i < lt and j < ls:
            if t[i] != s[j]:
                return False
            i += 1
            j += 1
        return True
    else:
        return False

