def minimizeStringValue(s: str) -> str:
    import heapq

    n = len(s)
    fixed_freq = [0] * 26
    q_count = 0

    for ch in s:
        if ch == '?':
            q_count += 1
        else:
            fixed_freq[ord(ch) - 97] += 1

    # Simulate adding the '?'s to the smallest available frequencies
    heap = []
    for i in range(26):
        heapq.heappush(heap, (fixed_freq[i], i))

    target_freq = fixed_freq[:]
    for _ in range(q_count):
        freq, letter = heapq.heappop(heap)
        target_freq[letter] += 1
        heapq.heappush(heap, (freq + 1, letter))

    # needed[i] = how many times we still need to place letter i in '?' positions
    needed = [target_freq[i] - fixed_freq[i] for i in range(26)]

    res = []
    for ch in s:
        if ch != '?':
            res.append(ch)
        else:
            # Pick the smallest letter that is still needed
            for i in range(26):
                if needed[i] > 0:
                    res.append(chr(i + 97))
                    needed[i] -= 1
                    break

    return ''.join(res)
