def min_anagram_length(s: str) -> int:
    n = len(s)
    # overall frequency of each character in the whole string
    overall = [0] * 26
    for ch in s:
        overall[ord(ch) - 97] += 1

    # try divisors in increasing order
    for d in range(1, n + 1):
        if n % d != 0:
            continue
        k = n // d                     # number of blocks

        # quick check: each character's total count must be divisible by k
        possible = True
        for cnt in overall:
            if cnt % k != 0:
                possible = False
                break
        if not possible:
            continue

        # frequency of the first block
        freq0 = [0] * 26
        for i in range(d):
            freq0[ord(s[i]) - 97] += 1

        # sliding window over the remaining blocks
        freq = freq0[:]                # mutable copy
        valid = True
        for start in range(d, n, d):
            # remove the block that just left the window
            for i in range(start - d, start):
                freq[ord(s[i]) - 97] -= 1
            # add the new block
            for i in range(start, start + d):
                freq[ord(s[i]) - 97] += 1
            # compare with the first block
            if freq != freq0:
                valid = False
                break

        if valid:
            return d

    # fallback (should never be reached because d = n always works)
    return n
