                    inv_row += 1

        for col_perm in itertools.permutations(cols):
            # Check if this permutation makes A equal to B
            ok = True
            for i in range(H):
                ri = row_perm[i]
                rowA = A[ri]
                rowB = B[i]
                for j in range(W):
                    cj = col_perm[j]
                    if rowA[cj] != rowB[j]:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue

            # Compute inversion count for column permutation
            inv_col = 0
            for i in range(W):
                for j in range(i+1, W):
                    if col_perm[i] > col_perm[j]:
                        inv_col += 1

            total = inv_row + inv_col
            if total < min_ops:
                min_ops = total

    if min_ops == float('inf'):
        print(-1)
    else:
        print(min_ops)

if __name__ == "__main__":
    solve()
