def sumOfPower(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    # dp[s][c] = number of subsets with sum s and size c
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for num in nums:
        # iterate backwards to avoid using the same element multiple times
        for s in range(k, num - 1, -1):
            for c in range(n, 0, -1):
                dp[s][c] = (dp[s][c] + dp[s - num][c - 1]) % MOD
    # precompute powers of 2
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD
    ans = 0
    for c in range(n + 1):
        if dp[k][c]:
            ans = (ans + dp[k][c] * pow2[n - c]) % MOD
    return ans
