def longestString(x: int, y: int, z: int) -> int:
    # dp[i][j][k][last] = maximum number of strings used
    # last: 0 = "AA", 1 = "BB", 2 = "AB"
    dp = [[[[-1] * 3 for _ in range(z + 1)] for _ in range(y + 1)] for _ in range(x + 1)]

    # Initialize with one string of each type
    if x > 0:
        dp[1][0][0][0] = 1
    if y > 0:
        dp[0][1][0][1] = 1
    if z > 0:
        dp[0][0][1][2] = 1

    # Allowed transitions: from last to next
    allowed = [[False] * 3 for _ in range(3)]
    allowed[0][1] = True  # AA -> BB
    allowed[1][0] = True  # BB -> AA
    allowed[1][2] = True  # BB -> AB
    allowed[2][0] = True  # AB -> AA
    allowed[2][2] = True  # AB -> AB

    # Fill DP table
    for i in range(x + 1):
        for j in range(y + 1):
            for k in range(z + 1):
                for last in range(3):
                    cur = dp[i][j][k][last]
                    if cur == -1:
                        continue
                    # Try to add each type of string
                    for t in range(3):
                        if not allowed[last][t]:
                            continue
                        ni, nj, nk = i, j, k
                        if t == 0:
                            ni += 1
                        elif t == 1:
                            nj += 1
                        else:
                            nk += 1
                        if ni <= x and nj <= y and nk <= z:
                            if dp[ni][nj][nk][t] < cur + 1:
                                dp[ni][nj][nk][t] = cur + 1

    # Find maximum length
    max_len = 0
    for i in range(x + 1):
        for j in range(y + 1):
            for k in range(z + 1):
                for last in range(3):
                    if dp[i][j][k][last] != -1:
                        max_len = max(max_len, 2 * (i + j + k))
    return max_len
