import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, delta):
        """add delta at 0-indexed idx"""
        i = idx + 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, idx):
        """prefix sum [0, idx] inclusive, idx 0-indexed"""
        if idx < 0:
            return 0
        i = idx + 1
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def range_sum(self, l, r):
        """sum over [l, r] inclusive, 0-indexed"""
        if l > r:
            return 0
        return self.sum(r) - self.sum(l - 1)

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    N = int(next(it))
    Q = int(next(it))
    S = list(next(it).strip())
    # Build A array of length N-1
    A = [0] * (N - 1)
    for i in range(N - 1):
        if S[i] == S[i + 1]:
            A[i] = 1
    fen = Fenwick(N - 1)
    for i, val in enumerate(A):
        if val == 1:
            fen.add(i, 1)

    out_lines = []
    for _ in range(Q):
        typ = int(next(it))
        L = int(next(it))
        R = int(next(it))
        if typ == 1:
            # flip range [L, R] (1-indexed)
            l0 = L - 1
            r0 = R - 1
            # update left boundary if L > 1
            if L > 1:
                idx = L - 2  # index in A corresponding to position L-1
                # toggle A[idx]
                if A[idx] == 1:
                    A[idx] = 0
                    fen.add(idx, -1)
                else:
                    A[idx] = 1
                    fen.add(idx, 1)
            # update right boundary if R < N
            if R < N:
                idx = R - 1  # index in A corresponding to position R
                if A[idx] == 1:
                    A[idx] = 0
                    fen.add(idx, -1)
                else:
                    A[idx] = 1
                    fen.add(idx, 1)
        else:  # typ == 2
            if L == R:
                out_lines.append("Yes")
            else:
                # sum over A[L-1 .. R-2] (0-indexed)
                l_idx = L - 1
                r_idx = R - 2
                s = fen.range_sum(l_idx, r_idx)
                out_lines.append("Yes" if s == 0 else "No")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
