def min_operations_to_make_median_k(nums, k):
    nums.sort()
    n = len(nums)
    m = n // 2
    ans = 0
    # Ensure the first m+1 elements are <= k
    for i in range(m + 1):
        if nums[i] > k:
            ans += nums[i] - k
    # Ensure the last n-m elements are >= k
    for i in range(m, n):
        if nums[i] < k:
            ans += k - nums[i]
    return ans
