def numberOfStableArrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7
    # dp0[i][j][r] : sequences with i zeros, j ones, ending with 0, run length r
    dp0 = [[[0] * (limit + 1) for _ in range(one + 1)] for __ in range(zero + 1)]
    # dp1[i][j][r] : sequences with i zeros, j ones, ending with 1, run length r
    dp1 = [[[0] * (limit + 1) for _ in range(one + 1)] for __ in range(zero + 1)]

    if zero > 0:
        dp0[1][0][1] = 1
    if one > 0:
        dp1[0][1][1] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            for r in range(1, limit + 1):
                # from state ending with 0
                val0 = dp0[i][j][r]
                if val0:
                    # add another 0 (only if run length < limit)
                    if i < zero and r < limit:
                        dp0[i + 1][j][r + 1] = (dp0[i + 1][j][r + 1] + val0) % MOD
                    # add a 1 (starts new run of 1s)
                    if j < one:
                        dp1[i][j + 1][1] = (dp1[i][j + 1][1] + val0) % MOD

                # from state ending with 1
                val1 = dp1[i][j][r]
                if val1:
                    # add another 1 (only if run length < limit)
                    if j < one and r < limit:
                        dp1[i][j + 1][r + 1] = (dp1[i][j + 1][r + 1] + val1) % MOD
                    # add a 0 (starts new run of 0s)
                    if i < zero:
                        dp0[i + 1][j][1] = (dp0[i + 1][j][1] + val1) % MOD

    ans = 0
    for r in range(1, limit + 1):
        ans = (ans + dp0[zero][one][r] + dp1[zero][one][r]) % MOD
    return ans
