def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    # count bits for positions 0..30 (since nums[i] <= 1e9 < 2^30)
    count = [0] * 31
    for num in nums:
        for b in range(31):
            if num & (1 << b):
                count[b] += 1

    # we will build k numbers, initially all zero
    arr = [0] * k

    # process bits from high to low
    for b in range(30, -1, -1):
        cnt = min(count[b], k)          # at most k copies can be used
        if cnt:
            val = 1 << b
            # add the bit to the largest cnt numbers (first cnt elements)
            for i in range(cnt):
                arr[i] += val

    # compute sum of squares modulo MOD
    total = 0
    for x in arr:
        total = (total + x * x) % MOD
    return total
