def min_equal_sum(nums1, nums2):
    sum1 = count1 = 0
    for x in nums1:
        if x == 0:
            count1 += 1
        else:
            sum1 += x

    sum2 = count2 = 0
    for x in nums2:
        if x == 0:
            count2 += 1
        else:
            sum2 += x

    # Both arrays have no zeros
    if count1 == 0 and count2 == 0:
        return sum1 if sum1 == sum2 else -1

    # Only nums1 has no zeros
    if count1 == 0:
        # sum1 is fixed, need to make nums2 sum equal to sum1
        if sum1 >= sum2 + count2:
            return sum1
        else:
            return -1

    # Only nums2 has no zeros
    if count2 == 0:
        if sum2 >= sum1 + count1:
            return sum2
        else:
            return -1

    # Both have zeros
    lower1 = sum1 + count1
    lower2 = sum2 + count2
    return max(lower1, lower2)
