def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    max_val = max(A) if A else 0
    # Precompute smallest prime factor (SPF) up to max_val
    limit = max(2, max_val)
    spf = list(range(limit + 1))
    for i in range(2, int(limit ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def squarefree_kernel(x: int) -> int:
        """Return the squarefree kernel of x (product of primes with odd exponent)."""
        res = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt ^= 1  # toggle parity
            if cnt:
                res *= p
        return res

    zero_cnt = 0
    freq = {}
    for val in A:
        if val == 0:
            zero_cnt += 1
        else:
            k = squarefree_kernel(val)
            freq[k] = freq.get(k, 0) + 1

    ans = 0
    # pairs among non‑zero numbers with same kernel
    for cnt in freq.values():
        ans += cnt * (cnt - 1) // 2
    # pairs involving zeros
    non_zero = N - zero_cnt
    ans += zero_cnt * non_zero          # zero * non‑zero
    ans += zero_cnt * (zero_cnt - 1) // 2  # zero * zero

    print(ans)

if __name__ == "__main__":
    solve()
