def punishment_number(n: int) -> int:
    def can_partition(s: str, target: int, start: int, current_sum: int) -> bool:
        if start == len(s):
            return current_sum == target
        if current_sum > target:
            return False
        for end in range(start + 1, len(s) + 1):
            part = int(s[start:end])
            if can_partition(s, target, end, current_sum + part):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(str(sq), i, 0, 0):
            total += sq
    return total
