def minimumCost(source, target, original, changed, cost):
    INF = 10**18
    n = 26
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    # Build direct edges with minimum cost
    for u_char, v_char, c in zip(original, changed, cost):
        u = ord(u_char) - ord('a')
        v = ord(v_char) - ord('a')
        if c < dist[u][v]:
            dist[u][v] = c

    # Floyd-Warshall for all-pairs shortest paths
    for k in range(n):
        for i in range(n):
            if dist[i][k] == INF:
                continue
            for j in range(n):
                if dist[k][j] == INF:
                    continue
                nd = dist[i][k] + dist[k][j]
                if nd < dist[i][j]:
                    dist[i][j] = nd

    total = 0
    for s_char, t_char in zip(source, target):
        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')
        if dist[u][v] == INF:
            return -1
        total += dist[u][v]

    return total
