def paintWalls(cost, time):
    n = len(cost)
    INF = 10**18  # large enough
    dp = [INF] * (n + 1)
    dp[0] = 0
    for c, t in zip(cost, time):
        weight = t + 1  # effective weight: time + 1
        # iterate backwards to avoid using the same item multiple times
        for w in range(n, -1, -1):
            if dp[w] != INF:
                new_w = min(n, w + weight)  # cap at n
                if dp[new_w] > dp[w] + c:
                    dp[new_w] = dp[w] + c
    return dp[n]
