def count_complete_substrings(word: str, k: int) -> int:
    n = len(word)
    if k > n:
        return 0

    ans = 0
    max_m = min(26, n // k)  # maximum possible number of distinct characters

    for m in range(1, max_m + 1):
        L = m * k
        if L > n:
            continue

        # frequency of each letter in the current window
        freq = [0] * 26
        # number of characters with frequency != 0 and != k
        bad_chars = 0
        # number of adjacent pairs with difference > 2
        invalid_pairs = 0

        # helper to check if a frequency is "bad"
        def is_bad(f: int) -> bool:
            return f != 0 and f != k

        # initialize first window
        for i in range(L):
            c = ord(word[i]) - ord('a')
            freq[c] += 1
        for f in freq:
            if is_bad(f):
                bad_chars += 1
        for i in range(L - 1):
            if abs(ord(word[i]) - ord(word[i + 1])) > 2:
                invalid_pairs += 1

        if bad_chars == 0 and invalid_pairs == 0:
            ans += 1

        # slide the window
        for start in range(1, n - L + 1):
            # remove leftmost character
            left_char = ord(word[start - 1]) - ord('a')
            old_left = freq[left_char]
            freq[left_char] -= 1
            new_left = freq[left_char]
            if is_bad(old_left):
                bad_chars -= 1
            if is_bad(new_left):
                bad_chars += 1

            # add new rightmost character
            right_char = ord(word[start + L - 1]) - ord('a')
            old_right = freq[right_char]
            freq[right_char] += 1
            new_right = freq[right_char]
            if is_bad(old_right):
                bad_chars -= 1
            if is_bad(new_right):
                bad_chars += 1

            # update invalid_pairs
            if L > 1:
                # remove the pair that is no longer in the window
                if abs(ord(word[start - 1]) - ord(word[start])) > 2:
                    invalid_pairs -= 1
                # add the new pair that enters the window
                if abs(ord(word[start + L - 2]) - ord(word[start + L - 1])) > 2:
                    invalid_pairs += 1

            if bad_chars == 0 and invalid_pairs == 0:
                ans += 1

    return ans
```

