import sys

def can_tile(H, W, tiles):
    """
    Returns True if the given list of tiles (each as (h, w)) can exactly cover
    an H x W grid. Tiles may be rotated.
    """
    # grid: False = empty, True = filled
    grid = [[False] * W for _ in range(H)]

    # sort tiles by area descending for better pruning
    tiles_sorted = sorted(tiles, key=lambda x: x[0] * x[1], reverse=True)

    def backtrack(remaining):
        # find first empty cell
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    # try each remaining tile
                    for idx, (h, w) in enumerate(remaining):
                        # try both orientations
                        orientations = [(h, w)]
                        if h != w:
                            orientations.append((w, h))
                        for dh, dw in orientations:
                            if r + dh <= H and c + dw <= W:
                                # check if the rectangle is free
                                ok = True
                                for i in range(dh):
                                    for j in range(dw):
                                        if grid[r + i][c + j]:
                                            ok = False
                                            break
                                    if not ok:
                                        break
                                if ok:
                                    # fill
                                    for i in range(dh):
                                        for j in range(dw):
                                            grid[r + i][c + j] = True
                                    # recurse without this tile
                                    new_remaining = remaining[:idx] + remaining[idx+1:]
                                    if backtrack(new_remaining):
                                        return True
                                    # unfill
                                    for i in range(dh):
                                        for j in range(dw):
                                            grid[r + i][c + j] = False
                    # no tile fits at this cell -> impossible
                    return False
        # no empty cell found -> all filled
        return True

    return backtrack(tiles_sorted)


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))
    tiles = []
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        tiles.append((a, b))

    total_cells = H * W
    areas = [a * b for a, b in tiles]

    # try every non‑empty subset of tiles
    for mask in range(1, 1 << N):
        area_sum = 0
        subset = []
        for i in range(N):
            if mask & (1 << i):
                area_sum += areas[i]
                subset.append(tiles[i])
        if area_sum != total_cells:
            continue
        if can_tile(H, W, subset):
            print("Yes")
            return
    print("No")


if __name__ == "__main__":
    solve()
