            if j >= K:
                left = row[j - K]
                if left == 'x':
                    x_cnt -= 1
                elif left == '.':
                    dot_cnt -= 1
            # window of length K is ready
            if j >= K - 1:
                if x_cnt == 0:
                    ans = min(ans, dot_cnt)

    # Vertical segments
    for j in range(W):
