from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n <= 1:
        return True

    max_val = max(nums)
    # Sieve to compute smallest prime factor (SPF) for numbers up to max_val
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Map from prime to the first index that contains it
    prime_to_index = {}

    for i, val in enumerate(nums):
        # Factorize val using SPF
        distinct_primes = set()
        while val > 1:
            p = spf[val]
            distinct_primes.add(p)
            while val % p == 0:
                val //= p
        for p in distinct_primes:
            if p in prime_to_index:
                union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
