def solve(queries):
    # Helper: count of numbers in [1, N] with bit i set
    def count_set_bit(N, i):
        period = 1 << (i + 1)
        full = (N + 1) // period
        rem = (N + 1) % period
        return full * (period // 2) + max(0, rem - (period // 2))

    # Total number of elements (popcount sum) from 1 to N
    def total_elements_up_to(N):
        if N <= 0:
            return 0
        total = 0
        max_bit = N.bit_length()
        for i in range(max_bit):
            total += count_set_bit(N, i)
        return total

    # Total exponent sum from 1 to N
    def total_exponent_sum_up_to(N):
        if N <= 0:
            return 0
        total = 0
        max_bit = N.bit_length()
        for i in range(max_bit):
            total += i * count_set_bit(N, i)
        return total

    # Sum of the first m set bits of N (bits in increasing order)
    def sum_first_m_set_bits(N, m):
        s = 0
        i = 0
        while m > 0 and N:
            if N & 1:
                s += i
                m -= 1
            N >>= 1
            i += 1
        return s

    # Prefix sum of exponents for first k elements (indices 0..k-1)
    def prefix_sum(k):
        if k == 0:
            return 0
        # Binary search for the smallest N such that total_elements_up_to(N) >= k
        lo, hi = 1, 10**15  # safe upper bound
        while lo < hi:
            mid = (lo + hi) // 2
            if total_elements_up_to(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        N = lo
        prev = total_elements_up_to(N - 1)
        m = k - prev
        return total_exponent_sum_up_to(N - 1) + sum_first_m_set_bits(N, m)

    ans = []
    for L, R, mod in queries:
        exp_sum = prefix_sum(R + 1) - prefix_sum(L)
        ans.append(pow(2, exp_sum, mod))
    return ans
