                if s > top2[1]:
                    top2[1] = s
                    if top2[0] < top2[1]:
                        top2[0], top2[1] = top2[1], top2[0]

    # Sort all cups by deliciousness descending
    cups.sort(reverse=True, key=lambda x: x[0])

