def minimum_mountain_sum(nums: List[int]) -> int:
    n = len(nums)
    min_sum = float('inf')

    # Precompute left minimums: for each index j, the smallest value to the left that is less than nums[j]
    left_min = [float('inf')] * n
    for j in range(1, n):
        # We can compute on the fly, but precomputing is fine
        pass

    # Actually, we can compute on the fly for each j
    for j in range(1, n - 1):
        # Find smallest left value less than nums[j]
        left_val = float('inf')
        for i in range(j):
            if nums[i] < nums[j] and nums[i] < left_val:
                left_val = nums[i]
        if left_val == float('inf'):
            continue

        # Find smallest right value less than nums[j]
        right_val = float('inf')
        for k in range(j + 1, n):
            if nums[k] < nums[j] and nums[k] < right_val:
                right_val = nums[k]
        if right_val == float('inf'):
            continue

        current_sum = left_val + nums[j] + right_val
