def minCost(s1: str, s2: str, x: int) -> int:
    diff = [i for i in range(len(s1)) if s1[i] != s2[i]]
    m = len(diff)

    if m % 2:
        return -1
    if m == 0:
        return 0

    INF = 10**18
    dp = [[0] * m for _ in range(m)]

    for length in range(2, m + 1, 2):
        for left in range(m - length + 1):
            right = left + length - 1
            best = INF

            for k in range(left + 1, right + 1, 2):
                cost = min(x, diff[k] - diff[left])

                if left + 1 <= k - 1:
                    cost += dp[left + 1][k - 1]
                if k + 1 <= right:
                    cost += dp[k + 1][right]

                if cost < best:
                    best = cost

            dp[left][right] = best

    return dp[0][m - 1]
