def min_groups(nums):
    freq = {}
    for x in nums:
        freq[x] = freq.get(x, 0) + 1

    counts = list(freq.values())
    min_freq = min(counts)
    ans = len(nums)

    for k in range(1, min_freq + 1):
        total = 0
        possible = True

        for c in counts:
            groups = (c + k) // (k + 1)  # ceil(c / (k + 1))
            if groups * k > c:
                possible = False
                break
            total += groups

        if possible:
            ans = min(ans, total)

    return ans
