import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    sets = []                     # list of lists of elements
    elem_to_sets = [[] for _ in range(M + 1)]   # 1-indexed

    for i in range(N):
        A = int(next(it))
        s = [int(next(it)) for _ in range(A)]
        sets.append(s)
        for e in s:
            elem_to_sets[e].append(i)

    # BFS on bipartite graph (set nodes and element nodes)
    dist_set = [-1] * N
    dist_elem = [-1] * (M + 1)
    q = deque()

    # start from all sets that contain 1
    for i, s in enumerate(sets):
        if 1 in s:
            dist_set[i] = 0
            q.append(('set', i))

    while q:
        typ, idx = q.popleft()
        if typ == 'set':
            # from a set, go to its elements (cost 0)
            for e in sets[idx]:
                if dist_elem[e] == -1:
                    dist_elem[e] = dist_set[idx]
                    q.append(('elem', e))
        else:  # typ == 'elem'
            # from an element, go to all sets containing it (cost 1)
            for s in elem_to_sets[idx]:
                if dist_set[s] == -1:
                    dist_set[s] = dist_elem[idx] + 1
                    q.append(('set', s))

    # find the minimum distance among sets that contain M
    ans = -1
    for i, s in enumerate(sets):
        if M in s and dist_set[i] != -1:
            if ans == -1 or dist_set[i] < ans:
                ans = dist_set[i]

    print(ans)

if __name__ == "__main__":
    solve()
```

