def countGoodPartitions(nums):
    MOD = 10**9 + 7
    first = {}
    last = {}
    for i, num in enumerate(nums):
        if num not in first:
            first[num] = i
        last[num] = i

    intervals = [(first[num], last[num]) for num in first]
    intervals.sort()

    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    blocks = len(merged)
    return pow(2, blocks - 1, MOD)
```

