def max_jumps(nums, target):
    n = len(nums)
    # dp[i] = maximum number of jumps to reach index i from index 0
    # Initialize with -inf (use -1 to indicate unreachable)
    dp = [-1] * n
    dp[0] = 0  # starting point, 0 jumps taken

    for i in range(n):
        if dp[i] == -1:
            continue  # cannot reach i, skip
        for j in range(i + 1, n):
            if -target <= nums[j] - nums[i] <= target:
                # we can jump from i to j
                dp[j] = max(dp[j], dp[i] + 1)

    return dp[n - 1]
```

