def min_operations_to_equal_strings(s1: str, s2: str, s3: str) -> int:
    # Find the length of the longest common prefix
    min_len = min(len(s1), len(s2), len(s3))
    L = 0
    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            L += 1
        else:
            break
    # If no common prefix, impossible
    if L == 0:
        return -1
    # Total operations = deletions needed for each string
    return (len(s1) - L) + (len(s2) - L) + (len(s3) - L)
```

