def maximumGoodSubarraySum(nums, k):
    min_prefix = {}
    prefix = 0
    ans = float('-inf')
    for val in nums:
        total_to_j = prefix + val
        # check for good subarrays ending at current index
        for target in (val + k, val - k):
            if target in min_prefix:
                candidate = total_to_j - min_prefix[target]
                if candidate > ans:
                    ans = candidate
        # update minimum prefix sum for current value
        if val not in min_prefix or prefix < min_prefix[val]:
            min_prefix[val] = prefix
        prefix = total_to_j
    return ans if ans != float('-inf') else 0
