    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x):
        # iterative path compression
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    for _ in range(M):
        u = int(next(it))
        v = int(next(it))
        union(u, v)

    K = int(next(it))
    bad = set()
    for _ in range(K):
        x = int(next(it))
        y = int(next(it))
        rx = find(x)
        ry = find(y)
        if rx != ry:
            if rx > ry:
                rx, ry = ry, rx
            bad.add((rx, ry))

