import sys

MOD = 998244353

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        # iterative path compression
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if self.rank[x] < self.rank[y]:
            self.parent[x] = y
        elif self.rank[x] > self.rank[y]:
            self.parent[y] = x
        else:
            self.parent[y] = x
            self.rank[x] += 1

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    H = int(data[0])
    W = int(data[1])
    grid = data[2:2+H]

    K = sum(row.count('.') for row in grid)

    dsu = DSU(H * W)

    # Union adjacent green cells
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                idx = i * W + j
                if i + 1 < H and grid[i+1][j] == '#':
                    dsu.union(idx, (i+1) * W + j)
                if j + 1 < W and grid[i][j+1] == '#':
                    dsu.union(idx, i * W + (j+1))

    # Count initial green components
    roots = set()
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                roots.add(dsu.find(i * W + j))
    C0 = len(roots)

    # Sum of distinct adjacent components for each red cell
    sum_d = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                adj_roots = set()
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                        adj_roots.add(dsu.find(ni * W + nj))
                sum_d += len(adj_roots)

    P = (C0 + 1) * K - sum_d
    Q = K
    ans = (P % MOD) * pow(Q, MOD - 2, MOD) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
```

