    tiles_sorted = sorted(enumerate(tiles), key=lambda x: x[1][0] * x[1][1], reverse=True)
    tile_indices = [idx for idx, _ in tiles_sorted]
    tile_dims = [dim for _, dim in tiles_sorted]

