        temp = x
        for p in prime_list:
            if p * p > temp:
                break
            if temp % p == 0:
                union(x, p)
                while temp % p == 0:
                    temp //= p
        if temp > 1:
            union(x, temp)

    # Check if all numbers in nums belong to the same connected component
    root = find(nums[0])
    for i in range(1, len(nums)):
