from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False

    max_val = max(nums)
    # Sieve to find smallest prime factor (SPF)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # DSU initialization
    size = n + max_val + 1
    parent = list(range(size))
    rank = [0] * size

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Connect each number to its prime factors
    for i, num in enumerate(nums):
        if num == 1:
            continue
        while num > 1:
            p = spf[num]
            union(i, n + p)
            while num % p == 0:
                num //= p

    # Check if all numbers are in the same component
    root0 = find(0)
    for i in range(1, n):
        if find(i) != root0:
            return False
    return True
