def get_lexicographically_smallest_string(s: str, k: int) -> str:
    t = []
    for ch in s:
        # Try to change ch to the smallest possible character
        for c in range(ord('a'), ord('z') + 1):
            target = chr(c)
            # Cyclic distance between ch and target
            diff = abs(ord(ch) - ord(target))
            dist = min(diff, 26 - diff)
            if dist <= k:
                t.append(target)
                k -= dist
                break
    return ''.join(t)
