        # Try x from largest possible (min frequency) down to 1
        for x in range(m, 0, -1):
            valid = True
            for f in frequencies:
                if f % x > f // x:
                    valid = False
                    break
            if valid:
                # For this x, the minimum number of groups is sum(ceil(f / (x+1)))
                total = 0
                for f in frequencies:
                    total += (f + x) // (x + 1)  # ceil(f / (x+1))
                return total
        return -1  # Should never be reached (x=1 is always valid)
```

