import sys

def solve() -> None:
    data = sys.stdin.read().splitlines()
    if not data:
        return
    H, W, N = map(int, data[0].split())
    T = data[1].strip()
    grid = data[2:2+H]

    # land_mask[i] has bit j set if grid[i][j] == '.'
    land_mask = []
    for row in grid:
        mask = 0
        for j, ch in enumerate(row):
            if ch == '.':
                mask |= (1 << j)
        land_mask.append(mask)

    # simulate the path to get all relative coordinates
    x, y = 0, 0
    offsets = {(0, 0)}
    for move in T:
        if move == 'L':
            y -= 1
        elif move == 'R':
            y += 1
        elif move == 'U':
            x -= 1
        else:  # 'D'
            x += 1
        offsets.add((x, y))

    full_mask = (1 << W) - 1
    valid = [full_mask] * H

    for dx, dy in offsets:
        for r in range(H):
            src = r + dx
            if 0 <= src < H:
                m = land_mask[src]
                if dy >= 0:
                    shifted = m >> dy
                else:
                    shifted = (m << (-dy)) & full_mask
            else:
                shifted = 0
            valid[r] &= shifted

    ans = sum(bin(v).count('1') for v in valid)
    print(ans)

if __name__ == "__main__":
    solve()
```

