def min_operations(s1, s2, s3):
    # If the first characters are not the same, they can never be equal
    if s1[0] != s2[0] or s1[0] != s3[0]:
        return -1

    # Find the length of the longest common prefix
    min_len = min(len(s1), len(s2), len(s3))
    common_len = 0
    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            common_len += 1
        else:
            break

    # The number of operations is the total number of characters 
    # removed from all three strings to reach the common prefix
    return (len(s1) - common_len) + (len(s2) - common_len) + (len(s3) - common_len)
```

